CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),cost INTEGER NOT NULL DEFAULT 0 CHECK(cost>=0),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),reorder_level INTEGER NOT NULL DEFAULT 10 CHECK(reorder_level>=0),art TEXT NOT NULL DEFAULT 'coffee',color TEXT NOT NULL DEFAULT '#eeeeee',active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS register_sessions(id BIGSERIAL PRIMARY KEY,opened_at TIMESTAMPTZ NOT NULL DEFAULT now(),closed_at TIMESTAMPTZ,opening_cash INTEGER NOT NULL CHECK(opening_cash>=0),closing_cash INTEGER CHECK(closing_cash>=0),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')));
CREATE UNIQUE INDEX IF NOT EXISTS one_open_register_session ON register_sessions(status) WHERE status='open';
CREATE TABLE IF NOT EXISTS sales(id BIGSERIAL PRIMARY KEY,session_id BIGINT NOT NULL REFERENCES register_sessions(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),total INTEGER NOT NULL CHECK(total>=0),payment TEXT NOT NULL CHECK(payment IN('cash','card')));
CREATE TABLE IF NOT EXISTS sale_items(id BIGSERIAL PRIMARY KEY,sale_id BIGINT NOT NULL REFERENCES sales(id),product_id BIGINT REFERENCES products(id),product_name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0));
CREATE TABLE IF NOT EXISTS purchases(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),supplier TEXT NOT NULL,invoice_number TEXT NOT NULL DEFAULT '',total INTEGER NOT NULL CHECK(total>=0),status TEXT NOT NULL CHECK(status IN('received','cancelled')));
CREATE TABLE IF NOT EXISTS purchase_items(id BIGSERIAL PRIMARY KEY,purchase_id BIGINT NOT NULL REFERENCES purchases(id),product_id BIGINT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_cost INTEGER NOT NULL CHECK(unit_cost>=0));
CREATE TABLE IF NOT EXISTS inventory_movements(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),product_id BIGINT NOT NULL REFERENCES products(id),kind TEXT NOT NULL CHECK(kind IN('opening','sale','purchase','adjustment')),quantity INTEGER NOT NULL CHECK(quantity<>0),reference_type TEXT,reference_id BIGINT,note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS petty_cash_entries(id BIGSERIAL PRIMARY KEY,session_id BIGINT NOT NULL REFERENCES register_sessions(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),direction TEXT NOT NULL CHECK(direction IN('in','out')),amount INTEGER NOT NULL CHECK(amount>0),category TEXT NOT NULL,note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('superadmin','admin','cashier')),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_sessions(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS auth_sessions_expiry ON auth_sessions(expires_at);
CREATE TABLE IF NOT EXISTS store_settings(id INTEGER PRIMARY KEY CHECK(id=1),currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','LKR','INR','EUR','GBP','AUD','CAD','SGD','AED','SAR')));
INSERT INTO store_settings(id,currency) VALUES(1,'USD') ON CONFLICT(id) DO NOTHING;
